"use client";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "./ui/avatar";
import { Button } from "@/components/ui/button";
import { Menu } from "lucide-react";
import { Switch } from "./ui/switch";

export default function Navbar({
  open,
  setOpen,
  doctorName,
  specialization,
  availability,
  isDoctor,
  setAvailability,
}) {
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const payload = JSON.parse(atob(token.split(".")[1]));
        setUser(payload);
      } catch {
        setUser(null);
      }
    }
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    router.push("/login");
  };

  return (
    <nav className="flex items-center justify-between shadow-md bg-gray-100 px-4 h-20 py-2 sticky top-0 z-50">
      <div className="flex items-center gap-2 mx-1.5">
        <Button variant="ghost" size="icon" onClick={() => setOpen(!open)}>
          <Menu className="w-6 h-6" />
        </Button>
        <div className="text-xl font-bold text-blue-700">DocHub</div>
      </div>

      <div>
        {user && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <div className="flex items-center gap-3 cursor-pointer">
                <Avatar>
                  <AvatarImage src={user.avatarUrl} alt={user.fullName} />
                  <AvatarFallback>{user.fullName?.charAt(0)}</AvatarFallback>
                </Avatar>

                {isDoctor && (
                  <>
                    <div className="flex flex-col">
                      <div className="text-base font-semibold text-gray-800">
                        {doctorName}
                      </div>

                      <div className="text-xs text-gray-500">
                        {specialization}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <Switch
                        checked={availability}
                        onCheckedChange={setAvailability}
                        id="availability-toggle"
                      />
                      <label
                        htmlFor="availability-toggle"
                        className={`text-xs font-medium ${
                          availability ? "text-green-600" : "text-red-500"
                        }`}
                      >
                        {availability ? "Online" : "Offline"}
                      </label>
                    </div>
                  </>
                )}
              </div>
            </DropdownMenuTrigger>

            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => router.push("/patient/profile")}>
                Profile
              </DropdownMenuItem>
              <DropdownMenuItem onClick={handleLogout}>Logout</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
    </nav>
  );
}
